library( inline )

c.code <- "
  SEXP res;
  int     nprotect = 0, nx, ny, x, y;
  double *dptr, *resptr, sum;
  PROTECT(res = Rf_duplicate(a)); nprotect++;
  nx = INTEGER(GET_DIM(a))[0];
  ny = INTEGER(GET_DIM(a))[1];
  dptr   = REAL(a);
  resptr = REAL( res );
  sum = 0.0;
  for (x = 0; x < nx; x++)
    for (y = 0; y < ny; y++)
    {
      resptr[ x + y*nx ] = -dptr[ x + y*nx ];
      sum += -dptr[ x + y*nx ];
    }
  UNPROTECT(nprotect);
  return res;
"
funx <- cfunction(signature(a="array"), c.code)
